import { CreateBucketCommand, DeleteObjectCommand, GetObjectCommand, HeadBucketCommand, ListObjectsV2Command, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { DOWNLOAD_LINK_SECONDS } from "../../lib/documents";
import { storageConfig } from "../config";

// Private object storage. The bucket is never public: bytes leave it only through short-lived signed URLs minted AFTER the
// database has authorised the caller (documents.storage_key_for). Keys are generated by the server, never taken from a client.

let io: S3Client | undefined;
let signer: S3Client | undefined;
const make = (endpoint: string) => {
  const c = storageConfig();
  return new S3Client({ endpoint, region: c.region, forcePathStyle: c.forcePathStyle, credentials: { accessKeyId: c.accessKey, secretAccessKey: c.secretKey } });
};
const client = () => (io ??= make(storageConfig().endpoint));
/** Signs against the browser-reachable endpoint (the host is part of the signature). Signing is local; no request is made. */
const urlSigner = () => (signer ??= make(storageConfig().publicEndpoint));

export async function putObject(key: string, body: Uint8Array, contentType: string): Promise<void> {
  await client().send(new PutObjectCommand({ Bucket: storageConfig().bucket, Key: key, Body: body, ContentType: contentType, CacheControl: "private, no-store" }));
}

export async function deleteObject(key: string): Promise<void> {
  await client().send(new DeleteObjectCommand({ Bucket: storageConfig().bucket, Key: key }));
}

/** A download link that works for DOWNLOAD_LINK_SECONDS. The response is forced to download as an opaque attachment. */
export async function signedDownloadUrl(key: string, filename: string, contentType: string): Promise<string> {
  const safe = filename.replace(/["\\\r\n]/g, "_");
  return getSignedUrl(urlSigner(), new GetObjectCommand({
    Bucket: storageConfig().bucket, Key: key,
    ResponseContentDisposition: `attachment; filename="${safe}"; filename*=UTF-8''${encodeURIComponent(filename)}`,
    ResponseContentType: contentType,
  }), { expiresIn: DOWNLOAD_LINK_SECONDS });
}

/** Creates the bucket if it does not exist (development / first deploy). Never changes any access policy. */
export async function ensureBucket(): Promise<void> {
  const Bucket = storageConfig().bucket;
  try {
    await client().send(new HeadBucketCommand({ Bucket }));
  } catch {
    await client().send(new CreateBucketCommand({ Bucket }));
  }
}

/** Lists every object key with its last-modified time (paged). Used only by the reconciliation tool. */
export async function listObjects(): Promise<{ key: string; lastModified: Date }[]> {
  const out: { key: string; lastModified: Date }[] = [];
  let token: string | undefined;
  do {
    const r = await client().send(new ListObjectsV2Command({ Bucket: storageConfig().bucket, ContinuationToken: token }));
    for (const o of r.Contents ?? []) if (o.Key && o.LastModified) out.push({ key: o.Key, lastModified: o.LastModified });
    token = r.IsTruncated ? r.NextContinuationToken : undefined;
  } while (token);
  return out;
}
